334	        claim.setTerms(rs.getInt("terms"));
335	        java.sql.Date deferred = rs.getDate("deferred_until");
336	        claim.setDeferredUntil(deferred == null ? null : deferred.toLocalDate());
337	        claim.setProofs(rs.getInt("proofs"));
338	        claim.setSplitFrom(rs.getString("split_from"));
339	        claim.setLateEntry(rs.getBoolean("late_entry"));
340	        java.sql.Date reminded = rs.getDate("reminded_on");
341	        claim.setRemindedOn(reminded == null ? null : reminded.toLocalDate());
342	        claim.setRef(rs.getString("ext_ref"));
