407	    public void unlock(Claim claim, String user) {
408	        if (user == null) {
409	            jdbc.update("UPDATE claim SET locked_by = NULL, locked_on = NULL WHERE id = ? AND sheet_id = ?",
410	                    claim.getId(), claim.getSheetId());
411	        } else {
412	            jdbc.update("UPDATE claim SET locked_by = NULL, locked_on = NULL WHERE id = ? AND sheet_id = ? AND locked_by = ?",
413	                    claim.getId(), claim.getSheetId(), user);
414	        }
415	    }
416	
417	    /** Whether a user other than {@code user} holds the claim's lock on {@code today}. */
418	    public boolean lockedByOther(Claim claim, String user, LocalDate today) {
419	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE id = ? AND sheet_id = ?"
420	                + " AND locked_by IS NOT NULL AND locked_by <> ? AND locked_on = ?",
421	                Integer.class, claim.getId(), claim.getSheetId(), user, Date.valueOf(today));
422	        return n != null && n > 0;
423	    }
424	
425	    /**
426	     * The sheet's next claim number, taken in one statement so two claims opened at the same
427	     * moment never share a number; it is never given out again.
428	     */
429	    public int nextNumber(String sheetId) {
430	        return jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE"
431	                + " (UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)",
432	                Integer.class, sheetId);
433	    }
434	
435	    /**
436	     * The next number in one period's sequence on the sheet ({@code sequence} '' for claims in no
437	     * period), counting from 1; taken in one statement so two claims opened at the same moment
438	     * never share a number, and never given out again.
439	     */
440	    public int nextNumberIn(String sheetId, String sequence) {
441	        jdbc.update("MERGE INTO period_number p USING (VALUES (CAST(? AS VARCHAR(200)), CAST(? AS VARCHAR(200)))) v (sheet_id, seq_name)"
442	                + " ON p.sheet_id = v.sheet_id AND p.seq_name = v.seq_name"
443	                + " WHEN NOT MATCHED THEN INSERT (sheet_id, seq_name, last_number) VALUES (v.sheet_id, v.seq_name, 0)",
444	                sheetId, sequence);
445	        return jdbc.queryForObject("SELECT last_number FROM FINAL TABLE"
446	                + " (UPDATE period_number SET last_number = last_number + 1 WHERE sheet_id = ? AND seq_name = ?)",
447	                Integer.class, sheetId, sequence);
448	    }
449	
450	    /**
451	     * The sheet's next bulk settle batch number, counting from 1; taken in one statement so two
452	     * bulk settles at the same moment never share a number, and never given out again.
453	     */
454	    public int nextBatch(String sheetId) {
455	        return jdbc.queryForObject("SELECT last_settle_batch FROM FINAL TABLE"
456	                + " (UPDATE sheet SET last_settle_batch = last_settle_batch + 1 WHERE id = ?)",
457	                Integer.class, sheetId);
458	    }
459	
460	    /**
461	     * The number of the sheet's last bulk settle batch, as it stood at the end of {@code day}
462	     * (null: now); null when there has been none.
463	     */
464	    public Integer lastBatch(String sheetId, LocalDate day) {
465	        if (day == null) {
466	            Integer last = jdbc.queryForObject("SELECT last_settle_batch FROM sheet WHERE id = ?", Integer.class, sheetId);
467	            return last == null || last == 0 ? null : last;
468	        }
469	        return jdbc.queryForObject("SELECT MAX(settle_batch) FROM claim_history WHERE sheet_id = ? AND set_on <= ?",
470	                Integer.class, sheetId, Date.valueOf(day));
471	    }
472	
473	    /** The sheet's next place in its claims list, taken in one statement; never given out again. */
474	    private long nextListed(String sheetId) {
475	        return jdbc.queryForObject("SELECT last_claim_listed FROM FINAL TABLE"
476	                + " (UPDATE sheet SET last_claim_listed = last_claim_listed + 1 WHERE id = ?)",
477	                Long.class, sheetId);
478	    }
479	
480	    /** A claim's statement binding: bound (to a figure, null: n/a) or not. */
481	    public record Binding(boolean stated, BigDecimal statedDue) {
482	    }
483	
484	    /**
485	     * Keeps the claim's binding in its history, with the sheet's today now, when it differs from
486	     * the one stored.
487	     */
488	    private void keepBinding(Claim claim) {
489	        List<Binding> stored = jdbc.query("SELECT stated, stated_due FROM claim WHERE id = ? AND sheet_id = ?",
490	                (rs, n) -> new Binding(rs.getBoolean("stated"), rs.getBigDecimal("stated_due")),
491	                claim.getId(), claim.getSheetId());
492	        if (!stored.isEmpty() && stored.get(0).stated() == claim.isStated()
493	                && same(stored.get(0).statedDue(), claim.getStatedDue())) return;
494	        jdbc.update("INSERT INTO claim_binding (sheet_id, claim_id, stated, stated_due, set_on)"
495	                + " VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
496	                claim.getSheetId(), claim.getId(), claim.isStated(), claim.getStatedDue(), claim.getSheetId());
497	    }
498	
499	    private static boolean same(BigDecimal a, BigDecimal b) {
500	        return a == null ? b == null : b != null && a.compareTo(b) == 0;
501	    }
502	
503	    /**
504	     * Each claim's binding at the end of {@code day}, by claim id: the last one given while the
505	     * sheet's today was on or before it. A claim with none then was unbound.
506	     */
507	    public Map<Long, Binding> bindingsOn(String sheetId, LocalDate day) {
508	        Map<Long, Binding> bindings = new HashMap<>();
509	        jdbc.query("SELECT claim_id, stated, stated_due FROM claim_binding WHERE sheet_id = ? AND set_on <= ? ORDER BY id",
510	                (rs) -> {
511	                    bindings.put(rs.getLong("claim_id"), new Binding(rs.getBoolean("stated"), rs.getBigDecimal("stated_due")));
512	                }, sheetId, Date.valueOf(day));
513	        return bindings;
514	    }
515	
516	    /**
517	     * Record the claim's reminder on its reminded date: only while it is still OPEN or PENDING and
518	     * not already reminded that day, so of two reminders at once only one is written.
519	     */
520	    public boolean remind(Claim claim) {
521	        Date on = Date.valueOf(claim.getRemindedOn());
522	        return jdbc.update("UPDATE claim SET reminded_on = ? WHERE id = ? AND sheet_id = ?"
523	                + " AND status IN ('OPEN', 'PENDING') AND (reminded_on IS NULL OR reminded_on <> ?)",
524	                on, claim.getId(), claim.getSheetId(), on) == 1;
525	    }
526	
527	    /** Whether another claim on the sheet than {@code exceptId} (null: any) has this reference, regardless of case. */
528	    public boolean refTaken(String sheetId, String ref, Long exceptId) {
529	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND UPPER(ext_ref) = UPPER(?)"
530	                + " AND id <> ?", Integer.class, sheetId, ref, exceptId == null ? -1L : exceptId);
531	        return n != null && n > 0;
532	    }
533	
534	    /** Insert a new claim (assigning its id) or update an existing one. */
535	    public void save(Claim claim) {
536	        if (claim.getId() != null) {
537	            if (claim.isRelisted()) {
538	                jdbc.update("UPDATE claim SET person_id = ?, listed = ? WHERE id = ? AND sheet_id = ?",
539	                        claim.getPersonId(), nextListed(claim.getSheetId()), claim.getId(), claim.getSheetId());
540	            }
541	            keepBinding(claim);
542	            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, claim_number = ?, settled_due = ?, opened_by = ?, edited_by = ?, stated = ?, stated_due = ?, corrects = ?, deferred_until = ?, proofs = ?, ext_ref = ?, tags = ?, void_reason = ?, settle_batch = ? WHERE id = ? AND sheet_id = ?",
543	                    claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(),
544	                    claim.getStatus().name(), claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(), claim.getEditedBy(),
545	                    claim.isStated(), claim.getStatedDue(), claim.getCorrects(),
546	                    claim.getDeferredUntil() == null ? null : Date.valueOf(claim.getDeferredUntil()), claim.getProofs(), claim.getRef(), claim.getTags(), claim.getVoidReason(), claim.getSettleBatch(), claim.getId(),
547	                    claim.getSheetId());
548	            keepHistory(claim);
549	            return;
550	        }
551	        long listed = nextListed(claim.getSheetId());
552	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
553	        jdbc.update(con -> {
554	            PreparedStatement ps = con.prepareStatement(
555	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, corrects, listed, due_by, split_from, claim_number, opened_by, late_entry, ext_ref, tags, terms) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
556	                    Statement.RETURN_GENERATED_KEYS);
557	            ps.setString(1, claim.getSheetId());
558	            ps.setLong(2, claim.getPersonId());
559	            ps.setBigDecimal(3, claim.getAmount());
560	            ps.setDate(4, Date.valueOf(claim.getDate()));
561	            ps.setString(5, claim.getNote());
562	            ps.setString(6, claim.getStatus().name());
563	            ps.setString(7, claim.getCorrects());
564	            ps.setLong(8, listed);
565	            ps.setDate(9, Date.valueOf(claim.getDueBy()));
566	            ps.setString(10, claim.getSplitFrom());
567	            ps.setString(11, claim.getNumber());
568	            ps.setString(12, claim.getOpenedBy());
569	            ps.setBoolean(13, claim.isLateEntry());
570	            ps.setString(14, claim.getRef());
571	            ps.setString(15, claim.getTags());
572	            ps.setInt(16, claim.getTerms());
573	            return ps;
574	        }, keys);
575	        claim.setId(keys.getKey().longValue());
576	        keepHistory(claim);
577	    }
578	
579	    /** Keep a due-by fixed again (its history kept, with the sheet's today now). */
580	    public void saveDueBy(Claim claim) {
581	        jdbc.update("UPDATE claim SET due_by = ? WHERE id = ? AND sheet_id = ?", Date.valueOf(claim.getDueBy()),
582	                claim.getId(), claim.getSheetId());
583	        keepHistory(claim);
584	    }
585	
586	    /**
587	     * Every tag ever used on the sheet, sorted: those its claims have been saved with, up to the end of
588	     * {@code day} (null: up to now).
589	     */
590	    public List<String> tagsUsed(String sheetId, LocalDate day) {
591	        java.util.TreeSet<String> tags = new java.util.TreeSet<>();
592	        jdbc.query("SELECT DISTINCT tags FROM claim_history WHERE sheet_id = ? AND tags IS NOT NULL"
593	                + (day == null ? "" : " AND set_on <= ?"), (rs) -> {
594	                    tags.addAll(List.of(rs.getString("tags").split(",")));
595	                }, day == null ? new Object[] { sheetId } : new Object[] { sheetId, Date.valueOf(day) });
596	        return List.copyOf(tags);
597	    }
598	
599	    private static final String HISTORY_COLUMNS = "person_id, amount, claim_date, note, status, claim_number, settled_due,"
600	            + " opened_by, stated, stated_due, corrects, due_by, deferred_until, proofs, split_from, late_entry, listed, tags, void_reason, settle_batch, ext_ref";
601	
602	    /** Keeps the claim as the store now holds it in its history, with the sheet's today now. */
603	    private void keepHistory(Claim claim) {
604	        jdbc.update("INSERT INTO claim_history (sheet_id, claim_id, " + HISTORY_COLUMNS + ", set_on)"
605	                + " SELECT sheet_id, id, " + HISTORY_COLUMNS + ", (SELECT s.today FROM sheet s WHERE s.id = claim.sheet_id)"
606	                + " FROM claim WHERE id = ? AND sheet_id = ?", claim.getId(), claim.getSheetId());
607	    }
608	
609	    /**
610	     * The sheet's claims as they stood at the end of {@code day}, newest first: each as last kept
611	     * while the sheet's today was on or before it (a claim added after is absent), locked by no one.
612	     */
613	    public List<Claim> findAllAsOf(String sheetId, LocalDate day) {
614	        Map<Long, Claim> latest = new HashMap<>();
615	        Map<Long, Long> listed = new HashMap<>();
616	        jdbc.query("SELECT claim_id, sheet_id, " + HISTORY_COLUMNS + " FROM claim_history WHERE sheet_id = ?"
617	                + " AND set_on <= ? ORDER BY id", (rs) -> {
618	                    Claim claim = new Claim(rs.getLong("claim_id"), rs.getString("sheet_id"), rs.getLong("person_id"),
619	                            rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
620	                            ClaimStatus.valueOf(rs.getString("status")), rs.getString("claim_number"),
621	                            rs.getBigDecimal("settled_due"), rs.getString("opened_by"));
622	                    claim.bind(rs.getBoolean("stated"), rs.getBigDecimal("stated_due"));
623	                    claim.setCorrects(rs.getString("corrects"));
624	                    claim.setDueBy(rs.getDate("due_by").toLocalDate());
625	                    Date deferred = rs.getDate("deferred_until");
626	                    claim.setDeferredUntil(deferred == null ? null : deferred.toLocalDate());
627	                    claim.setProofs(rs.getInt("proofs"));
628	                    claim.setSplitFrom(rs.getString("split_from"));
629	                    claim.setLateEntry(rs.getBoolean("late_entry"));
630	                    claim.setTags(rs.getString("tags"));
631	                    claim.setRef(rs.getString("ext_ref"));
632	                    claim.setVoidReason(rs.getString("void_reason"));
633	                    claim.setSettleBatch((Integer) rs.getObject("settle_batch", Integer.class));
634	                    latest.put(claim.getId(), claim);
635	                    listed.put(claim.getId(), rs.getLong("listed"));
636	                }, sheetId, Date.valueOf(day));
637	        for (Claim claim : latest.values()) {
638	            if (claim.getCorrects() == null) continue;
639	            latest.values().stream()
640	                    .filter((c) -> c.getPersonId() == claim.getPersonId() && claim.getCorrects().equals(c.getNumber()))
641	                    .findFirst().ifPresent((c) -> claim.setCorrectedDate(c.getDate()));
642	        }
643	        return latest.values().stream()
644	                .sorted(java.util.Comparator.comparing((Claim c) -> listed.get(c.getId())).thenComparing(Claim::getId)
645	                        .reversed())
646	                .toList();
647	    }
648	}
649	package net.officefloor.hq.app.claim;
650	
651	import net.officefloor.hq.app.period.Period;
652	import net.officefloor.hq.app.period.PeriodRepository;
653	import net.officefloor.hq.app.setting.Settings;
654	import net.officefloor.hq.app.sheet.Sheet;
655	
656	/**
657	 * The number a claim being opened takes: the sheet's next (1, 2, ...), or, while the sheet's period
658	 * numbering from is set and its today is on or after it, the next within the claim's period (the one containing its due-by)
659	 * (<period name>-<n>), or X-<n> when the claim is in no period.
660	 */
661	final class ClaimNumbers {
662	    private ClaimNumbers() {}
663	
664	    static String next(Sheet sheet, Claim claim, Settings settings, PeriodRepository periods, ClaimRepository claims) {
665	        if (!settings.numbersByPeriod(sheet.today())) return String.valueOf(claims.nextNumber(sheet.id()));
666	        Period period = periods.findAll(sheet.id()).stream()
667	                .filter((p) -> p.contains(claim.getDueBy())).findFirst().orElse(null);
668	        if (period == null) return "X-" + claims.nextNumberIn(sheet.id(), "");
669	        return period.name() + "-" + claims.nextNumberIn(sheet.id(), period.name());
670	    }
671	}
